use super::*;

fn node_fixture(_: &Tool, root: &Path) -> Result<(), Error> {
    for (path, bytes, mode) in [
        ("bin/node", b"#!/bin/sh\nexit 0\n".as_slice(), 0o755),
        ("lib/node_modules/npm/bin/npm-cli.js", b"npm fixture", 0o755),
        ("lib/node_modules/npm/bin/npx-cli.js", b"npx fixture", 0o755),
        (
            "lib/node_modules/npm/node_modules/@npmcli/config/package.json",
            b"{\"name\":\"@npmcli/config\"}",
            0o644,
        ),
        (
            "lib/node_modules/npm/node_modules/@npmcli/config/lib/index.js",
            b"scoped runtime resource",
            0o644,
        ),
        (
            "lib/node_modules/npm/node_modules/@isaacs/cliui/LICENSE.txt",
            b"scoped license",
            0o644,
        ),
        (
            "lib/node_modules/npm/.npmrc",
            b"hidden configuration",
            0o644,
        ),
        (
            "lib/node_modules/npm/node_modules/@npmcli/config/Bin/Helper",
            b"#!/bin/sh\nexit 0\n",
            0o700,
        ),
        ("include/node/v8-array-buffer.h", b"header fixture", 0o644),
        ("share/man/man1/node.1", b"manual fixture", 0o644),
        ("LICENSE", b"license fixture", 0o644),
    ] {
        let path = root.join(path);
        fs::create_dir_all(path.parent().ok_or(Error::UnsafePath)?)?;
        fs::write(&path, bytes)?;
        fs::set_permissions(path, fs::Permissions::from_mode(mode))?;
    }
    symlink(
        "../lib/node_modules/npm/bin/npm-cli.js",
        root.join("bin/npm"),
    )?;
    symlink(
        "../lib/node_modules/npm/bin/npx-cli.js",
        root.join("bin/npx"),
    )?;
    Ok(())
}

#[test]
fn scoped_node_tree_preserves_shims_resources_no_op_and_reuse() {
    let repo = tempfile::tempdir().unwrap();
    let mut store = Store::open(repo.path()).unwrap();
    let mut node = tool("node");
    node.executables = BTreeMap::from([
        ("node".into(), "bin/node".into()),
        ("npm".into(), "bin/npm".into()),
        ("npx".into(), "bin/npx".into()),
        (
            "helper".into(),
            "lib/node_modules/npm/node_modules/@npmcli/config/Bin/Helper".into(),
        ),
    ]);
    assert_eq!(
        store.reconcile(&[node.clone()], node_fixture).unwrap(),
        Outcome::Replaced
    );
    let before = manifest(&store);
    let bin = store.current().unwrap().unwrap().bin;
    assert_eq!(fs::read(bin.join("npm")).unwrap(), b"npm fixture");
    assert_eq!(fs::read(bin.join("npx")).unwrap(), b"npx fixture");
    assert!(Command::new(bin.join("node")).status().unwrap().success());
    assert!(Command::new(bin.join("helper")).status().unwrap().success());
    assert_eq!(
        fs::read_link(bin.join("npm")).unwrap(),
        Path::new("../tools/node/bin/npm")
    );
    assert_eq!(
        store
            .reconcile(&[node.clone()], |_, _| panic!(
                "healthy repeat must not stage"
            ))
            .unwrap(),
        Outcome::Unchanged
    );
    assert_eq!(manifest(&store), before);
    assert_eq!(store.current().unwrap().unwrap().bin, bin);

    // A changed inventory reuses the full node tree, including relative links,
    // while only the new tool goes through the callback.
    let pnpm = tool("pnpm");
    let mut staged = Vec::new();
    assert_eq!(
        store
            .reconcile(&[pnpm.clone(), node.clone()], |tool, root| {
                staged.push(tool.id.clone());
                populate(tool, root)
            })
            .unwrap(),
        Outcome::Replaced
    );
    assert_eq!(staged, ["pnpm"]);
    let current = store.current().unwrap().unwrap();
    let tree = current.bin.join("../tools/node");
    for (path, bytes) in [
        (
            "lib/node_modules/npm/node_modules/@npmcli/config/lib/index.js",
            b"scoped runtime resource".as_slice(),
        ),
        (
            "lib/node_modules/npm/node_modules/@isaacs/cliui/LICENSE.txt",
            b"scoped license",
        ),
        ("lib/node_modules/npm/.npmrc", b"hidden configuration"),
        ("LICENSE", b"license fixture"),
    ] {
        assert_eq!(fs::read(tree.join(path)).unwrap(), bytes);
    }
    assert_eq!(
        fs::read_link(tree.join("bin/npm")).unwrap(),
        Path::new("../lib/node_modules/npm/bin/npm-cli.js")
    );
    assert_eq!(fs::read(current.bin.join("npm")).unwrap(), b"npm fixture");
    assert_eq!(
        store
            .reconcile(&[node], |_, _| panic!("reuse must not stage"))
            .unwrap(),
        Outcome::Replaced
    );
    let current = store.current().unwrap().unwrap();
    assert!(!current.bin.join("pnpm").exists());
    assert_eq!(fs::read(current.bin.join("npx")).unwrap(), b"npx fixture");
}

#[test]
fn artifact_spelling_and_bookkeeping_identity_have_distinct_rules() {
    for name in [
        "@npmcli",
        "@isaacs",
        "LICENSE",
        ".npmrc",
        ".package-lock.json",
        "a+b",
        "a b",
    ] {
        assert!(artifact_component(name).is_ok(), "{name}");
    }
    assert!(relative("lib/node_modules/@npmcli/config/Bin/Helper").is_ok());
    for bad in [
        "",
        ".",
        "..",
        "NUL.txt",
        "CON .txt",
        "COM1",
        "lPt9.log",
        "CLOCK$",
        "CONIN$",
        "CONOUT$",
        "a/b",
        "a\\b",
        "C:tool",
        "tool:stream",
        "tool.",
        "tool ",
        "PROGRA~1",
        "a\0b",
        "a\nb",
        "é",
        "a?b",
        "a*b",
    ] {
        assert!(artifact_component(bad).is_err(), "{bad:?}");
    }
    assert!(artifact_component(&"a".repeat(256)).is_err());
    for bad in [
        "../tool",
        "/bin/tool",
        "bin//tool",
        "bin/./tool",
        "bin/../tool",
        "bin/tool:stream",
        "bin/NUL.txt",
    ] {
        assert!(relative(bad).is_err(), "{bad}");
    }
    assert!(relative(&"a/".repeat(2049)).is_err());
    let repo = tempfile::tempdir().unwrap();
    let mut store = Store::open(repo.path()).unwrap();
    for bad in ["@npmcli", "Node", "a+b", ".node", "node "] {
        let mut desired = tool("node");
        desired.id = bad.into();
        assert!(
            store
                .reconcile(&[desired], |_, _| panic!("invalid ID"))
                .is_err()
        );
        let mut desired = tool("node");
        desired.executables = BTreeMap::from([(bad.into(), "bin/tool".into())]);
        assert!(
            store
                .reconcile(&[desired], |_, _| panic!("invalid shim name"))
                .is_err()
        );
    }
    assert!(store.current().unwrap().is_none());
}

#[test]
fn unsafe_artifact_names_and_escaping_links_preserve_selected_generation() {
    let repo = tempfile::tempdir().unwrap();
    let mut store = Store::open(repo.path()).unwrap();
    let mut desired = tool("node");
    store.reconcile(&[desired.clone()], populate).unwrap();
    let before = manifest(&store);
    desired.version = "2.0.0".into();
    for bad in [
        "NUL.txt",
        "CON .txt",
        "tool:stream",
        "tool.",
        "a\\b",
        "PROGRA~1",
    ] {
        assert!(matches!(
            store.reconcile(&[desired.clone()], |tool, root| {
                populate(tool, root)?;
                fs::write(root.join(bad), b"unsafe artifact")?;
                Ok(())
            }),
            Err(Error::UnsafePath)
        ));
        assert_eq!(manifest(&store), before);
    }
    assert!(matches!(
        store.reconcile(&[desired], |tool, root| {
            populate(tool, root)?;
            symlink(repo.path(), root.join("@scope"))?;
            Ok(())
        }),
        Err(Error::UnsafePath)
    ));
    assert_eq!(manifest(&store), before);
    assert_eq!(
        fs::read(store.current().unwrap().unwrap().bin.join("node")).unwrap(),
        b"1.2.3"
    );
}

#[test]
fn direct_and_symlink_exports_require_owner_execute_before_publication() {
    for executable in ["bin/tool", "bin/alias"] {
        let repo = tempfile::tempdir().unwrap();
        let mut store = Store::open(repo.path()).unwrap();
        let mut desired = tool("node");
        desired.executables.insert("node".into(), executable.into());
        store.reconcile(&[desired.clone()], populate).unwrap();
        let before = manifest(&store);
        desired.version = "2.0.0".into();
        for mode in [0o600, 0o601, 0o610, 0o611, 0o645, 0o654] {
            assert!(
                matches!(
                    store.reconcile(&[desired.clone()], |tool, root| {
                        populate(tool, root)?;
                        fs::set_permissions(
                            root.join("bin/tool"),
                            fs::Permissions::from_mode(mode),
                        )?;
                        Ok(())
                    }),
                    Err(Error::InvalidInventory)
                ),
                "{mode:o}"
            );
            assert_eq!(manifest(&store), before);
            assert!(store.current().is_ok());
        }
        for mode in [0o700, 0o701, 0o710, 0o755] {
            desired.version = format!("2.{mode:o}");
            assert_eq!(
                store
                    .reconcile(&[desired.clone()], |tool, root| {
                        populate(tool, root)?;
                        fs::set_permissions(
                            root.join("bin/tool"),
                            fs::Permissions::from_mode(mode),
                        )?;
                        Ok(())
                    })
                    .unwrap(),
                Outcome::Replaced
            );
            let before = manifest(&store);
            assert_eq!(
                store
                    .reconcile(&[desired.clone()], |_, _| panic!("healthy repeat"))
                    .unwrap(),
                Outcome::Unchanged
            );
            assert_eq!(manifest(&store), before);
        }
    }
}

/// Ubuntu's default user umask is 0002. The umask is process-wide, so the
/// body runs in a re-executed copy of this test binary, not beside siblings.
#[test]
fn umask_0002_clone_gets_a_private_store_and_unsafe_directories_fail_closed() {
    const CHILD: &str = "TURBO_TOOL_INSTALL_UMASK_CHILD";
    if std::env::var_os(CHILD).is_none() {
        use std::os::unix::process::CommandExt;
        let mut command = Command::new(std::env::current_exe().unwrap());
        command
            .args([
                "--exact",
                "tests::paths_permissions::umask_0002_clone_gets_a_private_store_and_unsafe_directories_fail_closed",
                "--test-threads=1",
            ])
            .env(CHILD, "1");
        // SAFETY: umask is async-signal-safe and touches no heap or locks.
        unsafe {
            command.pre_exec(|| {
                libc::umask(0o002);
                Ok(())
            });
        }
        let output = command.output().unwrap();
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            output.status.success() && stdout.contains("1 passed"),
            "{stdout}{}",
            String::from_utf8_lossy(&output.stderr)
        );
        return;
    }
    let mode = |path: &Path| fs::symlink_metadata(path).unwrap().permissions().mode() & 0o7777;
    // A fresh clone, plus a `.turbo` that another turbo command created first.
    let repo = tempfile::tempdir().unwrap();
    fs::set_permissions(repo.path(), fs::Permissions::from_mode(0o775)).unwrap();
    let turbo = repo.path().join(".turbo");
    fs::create_dir(&turbo).unwrap();
    assert_eq!(mode(&turbo), 0o775);
    let mut store = Store::open(repo.path()).unwrap();
    store.reconcile(&[tool("node")], populate).unwrap();
    let generation = store.current().unwrap().unwrap().bin.join("..");
    drop(store);
    for (path, expected) in [
        (turbo.join("tools"), 0o700),
        (generation.clone(), 0o700),
        (generation.join("bin"), 0o700),
        (generation.join("tools/node"), 0o700),
        (turbo.join("tools/transaction.lock"), 0o600),
        (turbo.join("tools/manifest.json"), 0o600),
    ] {
        assert_eq!(mode(&path), expected, "{}", path.display());
    }
    assert!(Store::inspect(repo.path()).unwrap().is_some());
    for (path, unsafe_mode, restore) in [
        (repo.path().to_path_buf(), 0o777, 0o775),
        (turbo.clone(), 0o777, 0o775),
        (turbo.join("tools"), 0o770, 0o700),
        (generation.clone(), 0o770, 0o700),
    ] {
        fs::set_permissions(&path, fs::Permissions::from_mode(unsafe_mode)).unwrap();
        assert!(
            matches!(Store::inspect(repo.path()), Err(Error::UnsafePath)),
            "{}",
            path.display()
        );
        fs::set_permissions(&path, fs::Permissions::from_mode(restore)).unwrap();
    }
    assert!(Store::inspect(repo.path()).unwrap().is_some());
    // Unprivileged tests cannot chown; another user's private store is unsafe.
    let other = rustix::process::geteuid().as_raw().wrapping_add(1);
    assert!(!private_to_user(0o700, other));
}

#[test]
fn legacy_non_owner_executable_inventory_is_not_current_or_a_no_op() {
    let repo = tempfile::tempdir().unwrap();
    let mut store = Store::open(repo.path()).unwrap();
    let desired = tool("node");
    store
        .reconcile(std::slice::from_ref(&desired), populate)
        .unwrap();
    let mut inventory: Inventory = serde_json::from_slice(&manifest(&store)).unwrap();
    let tree = store.root.join(&inventory.generation).join("tools/node");
    fs::set_permissions(tree.join("bin/tool"), fs::Permissions::from_mode(0o601)).unwrap();
    // Model inventory published by the old validator: hash and bytes agree,
    // but the installation owner still cannot execute the mapped file.
    inventory.tools[0].tree_sha256 = tree_hash(&tree).unwrap();
    fs::write(
        store.root.join("manifest.json"),
        serde_json::to_vec(&inventory).unwrap(),
    )
    .unwrap();
    assert!(matches!(store.current(), Err(Error::InvalidInventory)));
    let mut stages = 0;
    assert_eq!(
        store
            .reconcile(&[desired], |tool, root| {
                stages += 1;
                populate(tool, root)
            })
            .unwrap(),
        Outcome::Replaced
    );
    assert_eq!(stages, 1);
    assert!(store.current().is_ok());
}

use std::{
    cell::Cell,
    os::unix::fs::{MetadataExt, PermissionsExt, symlink},
    path::Path,
    time::SystemTime,
};

use turborepo_setup::{
    activation::ActivationPlan,
    execution_identity::{ExecutionContext, Libc},
};
use turborepo_tool_install::Store;

use super::*;
use crate::commands::setup::authorization:[REDACTED], Error as AuthorizationError};

fn context() -> ExecutionContext {
    let libc = match provision::platform().unwrap() {
        turborepo_setup::lock::Platform::LinuxX64Gnu
        | turborepo_setup::lock::Platform::LinuxArm64Gnu => Libc::Gnu { abi: "gnu".into() },
        _ => Libc::None,
    };
    // Fixture context only, not runtime ABI/CPU qualification.
    ExecutionContext::new(
        turborepo_platform::Platform::current(),
        libc,
        "authorization-fixture".into(),
        ["baseline".into()].into(),
    )
    .unwrap()
}

fn inspect(f: &Fixture) -> Result<Authorization, AuthorizationError> {
    Authorization::inspect(
        f.owned.root(),
        f.owned.home(),
        context(),
        Default::default(),
    )
}

fn installed() -> (Fixture, Upstream) {
    let f = Fixture::new();
    let u = Upstream::new(&f, false, None);
    f.run(&u, FROZEN).unwrap();
    (f, u)
}

fn record(f: &Fixture) -> PathBuf {
    fs::read_dir(f.owned.home().join("turborepo/setup-roots"))
        .unwrap()
        .next()
        .unwrap()
        .unwrap()
        .path()
}

#[derive(Debug, PartialEq, Eq)]
struct Entry(PathBuf, u32, SystemTime, Vec<u8>, Option<PathBuf>);

// Include all owned state: repo, Git index, generations, locks and user state.
fn snapshot(root: &Path) -> Vec<Entry> {
    fn visit(path: &Path, entries: &mut Vec<Entry>) {
        let metadata = fs::symlink_metadata(path).unwrap();
        let link = metadata.file_type().is_symlink();
        entries.push(Entry(
            path.to_owned(),
            metadata.mode(),
            metadata.modified().unwrap(),
            if metadata.is_file() {
                fs::read(path).unwrap()
            } else {
                vec![]
            },
            if link {
                Some(fs::read_link(path).unwrap())
            } else {
                None
            },
        ));
        if metadata.is_dir() {
            for entry in fs::read_dir(path).unwrap() {
                visit(&entry.unwrap().path(), entries);
            }
        }
    }
    let mut entries = vec![];
    visit(root, &mut entries);
    entries.sort_by(|a, b| a.0.cmp(&b.0));
    entries
}

fn rejects_without_effects(f: &Fixture, u: &Upstream, selected: &Authorization) {
    let before = snapshot(f.owned.root().parent().unwrap());
    let hits = u.hits();
    let called = Cell::new(false);
    let error = selected.with_current(|_| called.set(true)).unwrap_err();
    assert!(error.to_string().contains("turbo setup"), "{error}");
    assert!(!called.get());
    assert!(inspect(f).is_err());
    assert_eq!(snapshot(f.owned.root().parent().unwrap()), before);
    assert_eq!(u.hits(), hits);
    f.no_execution();
}

#[test]
fn authorization_success_is_readonly_and_rechecks_at_every_use_without_locks() {
    let (f, u) = installed();
    fs::remove_file(f.owned.root().join(".turbo/tools/transaction.lock")).unwrap();
    let before = snapshot(f.owned.root().parent().unwrap());
    let environment: std::collections::BTreeMap<_, _> = std::env::vars_os().collect();
    let selected = inspect(&f).unwrap();
    for _ in 0..2 {
        selected
            .with_current(|plan| {
                assert_eq!(plan.tools().len(), 2);
                assert!(plan.runtime_env().is_empty());
                let path = plan.path(Some(std::ffi::OsStr::new("/host/bin"))).unwrap();
                let entries: Vec<_> = std::env::split_paths(&path).collect();
                assert_eq!(
                    entries,
                    vec![plan.path_prepend().to_owned(), "/host/bin".into()]
                );
            })
            .unwrap();
    }
    assert_eq!(snapshot(f.owned.root().parent().unwrap()), before);
    assert_eq!(
        std::env::vars_os().collect::<std::collections::BTreeMap<_, _>>(),
        environment
    );
    assert_eq!(u.hits(), 3);
    f.no_execution();

    // Neither inspection nor use may acquire producer locks.
    let sources = f.sources().unwrap();
    let writer = sources.guard().unwrap();
    let store = Store::open(f.owned.root()).unwrap();
    std::thread::scope(|scope| {
        let (send, receive) = std::sync::mpsc::channel();
        let fixture = &f;
        let pending = scope.spawn(move || {
            send.send(inspect(fixture).and_then(|a| a.with_current(|_| ())))
                .unwrap()
        });
        let result = receive.recv_timeout(std::time::Duration::from_secs(5));
        drop(store);
        drop(writer);
        pending.join().unwrap();
        result.unwrap().unwrap();
    });
}

#[test]
fn removed_corrupt_stale_or_unsafe_external_records_never_authorize() {
    for case in 0..14 {
        let (f, u) = installed();
        let selected = inspect(&f).unwrap();
        let path = record(&f);
        let mut value: Value = serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
        match case {
            0 => fs::remove_file(&path).unwrap(),
            1 => fs::write(&path, "corrupt").unwrap(),
            2 => {
                value["schema"] = json!(2);
            }
            3 => {
                value["lock_sha256"] = json!("0".repeat(64));
            }
            4 => {
                value["installation"]["manifest_sha256"] = json!("0".repeat(64));
            }
            5 => {
                value["installation"]["bin"] = json!(f.owned.root().join(".turbo/tools/bin"));
            }
            6 => {
                value["installation"]["inode"] = json!(0);
            }
            7 => {
                value["installation"]["tools"][0]["executables"] = json!({"git":"bin/node"});
            }
            8 => {
                value["installation"]["root"] = json!(f.owned.home());
            }
            9 => fs::set_permissions(&path, fs::Permissions::from_mode(0o644)).unwrap(),
            10 => fs::set_permissions(path.parent().unwrap(), fs::Permissions::from_mode(0o777))
                .unwrap(),
            11 => {
                fs::remove_file(&path).unwrap();
                symlink(f.owned.root().join("turbo.lock"), &path).unwrap();
            }
            12 => fs::hard_link(&path, f.owned.root().join("committed-record")).unwrap(),
            _ => {
                value["unknown"] = json!(true);
            }
        }
        if matches!(case, 2..=8 | 13) {
            fs::write(&path, value.to_string()).unwrap();
        }
        rejects_without_effects(&f, &u, &selected);
    }
}

