            f.owned.root()
        } else {
            moved.as_path()
        };
        assert!(ActivationPlan::inspect(root, context()).is_ok());
        assert!(
            Authorization:[REDACTED], f.owned.home(), context(), Default::default()).is_err()
        );
        assert_eq!(snapshot(f.owned.root().parent().unwrap()), before);
